#!/usr/bin/env bash
#
# Generates browser/branding/kavacha inside the Firefox checkout from Firefox's
# own `browser/branding/unofficial` template, replacing brand strings, URLs and
# imagery with Kavacha's. Source of truth: browser/branding/kavacha/branding.json
# and browser/branding/kavacha/assets/. The output is untracked in the checkout
# and regenerated by `bootstrap.sh setup|update|brand`; safe to re-run any time.
#
# Every platform's assets are produced here — PNG sizes, Windows .ico files,
# NSIS installer bitmaps, VisualElements manifests, and (on macOS) .icns — so
# a build on any host ships Kavacha imagery everywhere the packager looks.
# Requires Python 3 with Pillow (`python3 -m pip install pillow`).
#
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SRC_DIR="${SRC_DIR:-$REPO_ROOT/browser/firefox-source}"
TEMPLATE="$SRC_DIR/browser/branding/unofficial"
DST="$SRC_DIR/browser/branding/kavacha"
BRAND_DIR="$REPO_ROOT/browser/branding/kavacha"
LOGO="$BRAND_DIR/assets/logo.png"
BRAND_JSON="$BRAND_DIR/branding.json"

log()  { printf '\033[1;36m[kavacha]\033[0m %s\n' "$*"; }
fail() { printf '\033[1;31m[kavacha] ERROR:\033[0m %s\n' "$*" >&2; exit 1; }

[ -d "$TEMPLATE" ] || fail "$TEMPLATE missing — run ./build/bootstrap.sh setup first."
[ -f "$LOGO" ]     || fail "$LOGO missing."
[ -f "$BRAND_JSON" ] || fail "$BRAND_JSON missing."

PY="${PYTHON3:-python3}"
"$PY" -c 'import PIL' 2>/dev/null || {
    log "Pillow missing for $PY — installing..."
    "$PY" -m pip install --quiet pillow || fail "Could not install Pillow: $PY -m pip install pillow"
}

# Brand values from branding.json (single source of truth).
readjson() { "$PY" -c "import json,sys; d=json.load(open(sys.argv[1])); print(eval('d'+sys.argv[2]))" "$BRAND_JSON" "$1"; }
APP_NAME="$(readjson "['appName']")"
VENDOR="$(readjson "['vendor']")"
URL_HOME="$(readjson "['urls']['homepage']")"
URL_SUPPORT="$(readjson "['urls']['support']")"
URL_RELEASES="$(readjson "['urls']['releaseNotes']")"
SURFACE="$(readjson "['identity']['colors']['brandSurface']")"

log "Generating $APP_NAME branding at browser/branding/kavacha (template: unofficial)..."
# Windows can hold a freshly written file open (indexer/AV) for a moment;
# retry the removal rather than let a half-removed directory poison the copy.
for _ in 1 2 3 4 5; do
    rm -rf "$DST" 2>/dev/null && break
    sleep 2
done
[ ! -e "$DST" ] || fail "Could not remove $DST (file in use) — close programs using it and re-run."
mkdir -p "$DST"
# Copy the template's *contents* so this is correct whether or not $DST existed.
cp -R "$TEMPLATE/." "$DST/"
grep -q "^browser/branding/kavacha/$" "$SRC_DIR/.git/info/exclude" 2>/dev/null \
    || echo "browser/branding/kavacha/" >> "$SRC_DIR/.git/info/exclude"

# ---------------------------------------------------------------------------
# Text files
# ---------------------------------------------------------------------------
cat > "$DST/configure.sh" <<EOF
# This Source Code Form is subject to the terms of the Mozilla Public
# License, v. 2.0. If a copy of the MPL was not distributed with this
# file, You can obtain one at http://mozilla.org/MPL/2.0/.

MOZ_APP_DISPLAYNAME=$APP_NAME
MOZ_MACBUNDLE_ID=kavacha
EOF

cat > "$DST/locales/en-US/brand.ftl" <<EOF
# This Source Code Form is subject to the terms of the Mozilla Public
# License, v. 2.0. If a copy of the MPL was not distributed with this
# file, You can obtain one at http://mozilla.org/MPL/2.0/.

-brand-shorter-name = $APP_NAME
-brand-short-name = $APP_NAME
-brand-shortcut-name = $APP_NAME
-brand-full-name = $APP_NAME
# This brand name can be used in messages where the product name needs to
# remain unchanged across different versions (Nightly, Beta, etc.).
-brand-product-name = $APP_NAME
-vendor-short-name = $VENDOR
trademarkInfo = { " " }
EOF

cat > "$DST/locales/en-US/brand.properties" <<EOF
# This Source Code Form is subject to the terms of the Mozilla Public
# License, v. 2.0. If a copy of the MPL was not distributed with this
# file, You can obtain one at http://mozilla.org/MPL/2.0/.

brandShorterName=$APP_NAME
brandShortName=$APP_NAME
brandFullName=$APP_NAME
vendorShortName=$VENDOR
EOF

# Branding prefs. These load after firefox.js defaults (libpref loads defaults
# reverse-alphabetically), so they win conflicts. app.update.url is set here —
# it is the authoritative update URL; MOZ_APPUPDATE_HOST has no configure
# option in Firefox 153 (build/moz.build reads a CONFIG value nothing sets).
cat > "$DST/pref/firefox-branding.js" <<EOF
/* This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this
 * file, You can obtain one at http://mozilla.org/MPL/2.0/. */

// Kavacha branding prefs — generated by build/generate-branding.sh from
// browser/branding/kavacha/branding.json. Edit the generator, not this file.

pref("startup.homepage_override_url", "");
// First run opens Kavacha's own welcome (about:kavacha-welcome, ADR 0020 §4d);
// Firefox's about:welcome is not used.
pref("startup.homepage_welcome_url", "about:kavacha-welcome");
pref("startup.homepage_welcome_url.additional", "");
pref("browser.aboutwelcome.enabled", false);

// Updates: served by Kavacha's own update service (SHIPPING.md R1). Until it
// exists this host answers nothing, which fails closed.
pref("app.update.url", "https://updates.kavacha.app/update/6/%PRODUCT%/%VERSION%/%BUILD_ID%/%BUILD_TARGET%/%LOCALE%/%CHANNEL%/%OS_VERSION%/%SYSTEM_CAPABILITIES%/%DISTRIBUTION%/%DISTRIBUTION_VERSION%/update.xml");
pref("app.update.interval", 86400);
pref("app.update.promptWaitTime", 691200);
pref("app.update.url.manual", "$URL_HOME/download/");
pref("app.update.url.details", "$URL_RELEASES/");
pref("app.update.checkInstallTime.days", 2);
pref("app.update.badgeWaitTime", 0);
pref("app.releaseNotesURL", "$URL_RELEASES/");
pref("app.releaseNotesURL.aboutDialog", "$URL_RELEASES/%VERSION%/");
pref("app.releaseNotesURL.prompt", "$URL_RELEASES/");
pref("app.support.baseURL", "$URL_SUPPORT/");

pref("devtools.selfxss.count", 5);
EOF

# Ship the Kavacha defaults inside the app: firefox-branding.js is packaged as
# application default prefs (JS_PREFERENCE_FILES in branding-common.mozbuild).
# Sources of truth: privacy/tracker-controls/kavacha.js, ui/defaults/kavacha-ux.js.
{
    echo ""
    echo "// ============================================================================"
    echo "// Kavacha privacy defaults — generated from privacy/tracker-controls/kavacha.js"
    echo "// ============================================================================"
    cat "$REPO_ROOT/privacy/tracker-controls/kavacha.js"
    echo ""
    echo "// ============================================================================"
    echo "// Kavacha UX defaults — generated from ui/defaults/kavacha-ux.js"
    echo "// ============================================================================"
    cat "$REPO_ROOT/ui/defaults/kavacha-ux.js"
} >> "$DST/pref/firefox-branding.js"
log "Privacy + UX defaults appended ($(cat "$REPO_ROOT/privacy/tracker-controls/kavacha.js" "$REPO_ROOT/ui/defaults/kavacha-ux.js" | grep -c '^pref(') prefs)."
grep -q 'app.update.url", "https://updates.kavacha.app/' "$DST/pref/firefox-branding.js" || fail "app.update.url not set"

# NSIS installer defines. Keep the template's layout/colour block; replace identity.
NSI="$DST/branding.nsi"
NSIS_BG="0x${SURFACE#\#}"
sed -i.bak \
    -e "s|^!define BrandFullNameInternal .*|!define BrandFullNameInternal \"$APP_NAME\"|" \
    -e "s|^!define BrandFullName .*|!define BrandFullName         \"$APP_NAME\"|" \
    -e "s|^!define CompanyName .*|!define CompanyName           \"$VENDOR\"|" \
    -e "s|^!define URLInfoAbout .*|!define URLInfoAbout          \"$URL_HOME\"|" \
    -e "s|^!define HelpLink .*|!define HelpLink              \"$URL_SUPPORT\"|" \
    -e "s|^!define URLStubDownloadX86 .*|!define URLStubDownloadX86 \"$URL_HOME/download/?os=win\&lang=\${AB_CD}\"|" \
    -e "s|^!define URLStubDownloadAMD64 .*|!define URLStubDownloadAMD64 \"$URL_HOME/download/?os=win64\&lang=\${AB_CD}\"|" \
    -e "s|^!define URLStubDownloadAArch64 .*|!define URLStubDownloadAArch64 \"$URL_HOME/download/?os=win64-aarch64\&lang=\${AB_CD}\"|" \
    -e "s|^!define URLManualDownload .*|!define URLManualDownload \"$URL_HOME/download/\"|" \
    -e "s|^!define URLSystemRequirements .*|!define URLSystemRequirements \"$URL_SUPPORT/system-requirements/\"|" \
    -e "s|^!define Channel .*|!define Channel \"kavacha\"|" \
    -e "s|^!define COMMON_BACKGROUND_COLOR .*|!define COMMON_BACKGROUND_COLOR $NSIS_BG|" \
    "$NSI"
rm -f "$NSI.bak"
grep -q "BrandFullNameInternal \"$APP_NAME\"" "$NSI" || fail "branding.nsi rewrite failed"

# Windows Start tiles: keep the file names the packager expects, recolour.
for m in "$DST/firefox.VisualElementsManifest.xml" "$DST/private_browsing.VisualElementsManifest.xml"; do
    sed -i.bak -e "s|BackgroundColor='#[0-9a-fA-F]*'|BackgroundColor='$SURFACE'|" "$m" && rm -f "$m.bak"
done

# About dialog: the template paints Nightly's purple; use the Kavacha surface.
sed -i.bak -e "s|background-color: #130829;|background-color: $SURFACE;|" "$DST/content/aboutDialog.css" && rm -f "$DST/content/aboutDialog.css.bak"

# Wordmarks: use a Kavacha SVG if one exists, else the template's stays and is
# flagged so nobody mistakes a Nightly wordmark for done.
if [ -f "$BRAND_DIR/assets/wordmark.svg" ]; then
    cp "$BRAND_DIR/assets/wordmark.svg" "$DST/content/about-wordmark.svg"
    cp "$BRAND_DIR/assets/wordmark.svg" "$DST/content/firefox-wordmark.svg"
else
    log "NOTE: no assets/wordmark.svg — about dialog keeps the template wordmark."
fi

# ---------------------------------------------------------------------------
# Imagery: every raster the template ships, re-rendered from the Kavacha logo.
# ---------------------------------------------------------------------------
log "Rendering icons, tiles, .ico files and installer bitmaps from assets/logo.png..."
"$PY" - "$LOGO" "$DST" "$SURFACE" <<'PY'
import sys, os
from PIL import Image, ImageOps

logo_path, dst, surface = sys.argv[1], sys.argv[2], sys.argv[3]
logo = Image.open(logo_path).convert("RGBA")
bg = tuple(int(surface.lstrip("#")[i:i+2], 16) for i in (0, 2, 4))

def sq(size):
    return logo.resize((size, size), Image.LANCZOS)

def save_png(size, rel):
    p = os.path.join(dst, rel); os.makedirs(os.path.dirname(p), exist_ok=True)
    sq(size).save(p, "PNG")

# Chrome / GTK / about: sizes present in the unofficial template.
for s in (16, 22, 24, 32, 48, 64, 128, 256):
    save_png(s, f"default{s}.png")
save_png(192, "content/about-logo.png")
save_png(384, "content/about-logo@2x.png")
save_png(192, "content/about-logo-private.png")
save_png(384, "content/about-logo-private@2x.png")
# Template sizes: about.png is 300x236 (logo on a transparent canvas); the
# Start tiles ship at scale-200 (300 px for the 150 tile, 140 for the 70).
canvas = Image.new("RGBA", (300, 236), (0, 0, 0, 0)); mark = sq(200); canvas.paste(mark, (50, 18), mark)
canvas.save(os.path.join(dst, "content", "about.png"), "PNG")
for s, name in ((300, "VisualElements_150.png"), (140, "VisualElements_70.png"),
                (300, "PrivateBrowsing_150.png"), (140, "PrivateBrowsing_70.png")):
    save_png(s, name)

# Windows .ico: the exe icon plus the document/new-window/new-tab/private icons
# the resource script and installer reference by these exact names.
ico_sizes = [(16, 16), (24, 24), (32, 32), (48, 48), (64, 64), (128, 128), (256, 256)]
for name in ("firefox.ico", "document.ico", "document_pdf.ico", "newtab.ico", "newwindow.ico", "pbmode.ico"):
    sq(256).save(os.path.join(dst, name), format="ICO", sizes=ico_sizes)
sq(64).save(os.path.join(dst, "firefox64.ico"), format="ICO", sizes=[(16, 16), (32, 32), (48, 48), (64, 64)])

# NSIS bitmaps: 24-bit BMP, no alpha. Header 150x57 with the logo at the left;
# watermark 164x314 with the logo in the upper third. RTL header is mirrored.
def composite(w, h, logo_px, x, y):
    canvas = Image.new("RGB", (w, h), bg)
    mark = sq(logo_px)
    canvas.paste(mark, (x, y), mark)
    return canvas
header = composite(150, 57, 45, 6, 6)
header.save(os.path.join(dst, "wizHeader.bmp"), "BMP")
ImageOps.mirror(header).save(os.path.join(dst, "wizHeaderRTL.bmp"), "BMP")
composite(164, 314, 120, 22, 40).save(os.path.join(dst, "wizWatermark.bmp"), "BMP")

# Stub installer background (template ships 1344x822 JPEG).
stub = os.path.join(dst, "stubinstaller", "bgstub.jpg")
if os.path.exists(stub):
    composite(1344, 822, 360, 492, 180).save(stub, "JPEG", quality=90)

# MSIX tiles are not built by Kavacha; leave the template's. macOS Assets.car,
# disk.icns, dsstore and background.png are produced by other tooling.
print("ok")
PY

if [ "$(uname -s)" = "Darwin" ]; then
    log "Building firefox.icns via iconutil..."
    ICONSET="$(mktemp -d)/kavacha.iconset"
    mkdir -p "$ICONSET"
    for size in 16 32 128 256 512; do
        "$PY" -c "from PIL import Image; import sys; Image.open(sys.argv[1]).convert('RGBA').resize((int(sys.argv[3]),)*2, Image.LANCZOS).save(sys.argv[2])" "$LOGO" "$ICONSET/icon_${size}x${size}.png" "$size"
        "$PY" -c "from PIL import Image; import sys; Image.open(sys.argv[1]).convert('RGBA').resize((int(sys.argv[3]),)*2, Image.LANCZOS).save(sys.argv[2])" "$LOGO" "$ICONSET/icon_${size}x${size}@2x.png" "$((size * 2))"
    done
    iconutil -c icns "$ICONSET" -o "$DST/firefox.icns"
    rm -rf "$(dirname "$ICONSET")"
else
    log "NOTE: firefox.icns kept from the template (only macOS hosts render it; unused on this platform)."
fi

log "Branding generated at $DST."
